import math


def feature_points(width, height, jitter, rand):
    points = {}
    for cy in range(height):
        for cx in range(width):
            points[(cx, cy)] = (cx + jitter * rand(cx, cy, 0),
                                cy + jitter * rand(cx, cy, 1))
    return points


def worley(x, y, points, width, height, metric="euclidean", wrap=False):
    if metric not in ("euclidean", "manhattan", "chebyshev"):
        raise ValueError(f"unknown metric {metric!r}")
    if width < 1 or height < 1:
        raise ValueError("the cell grid must be at least 1 by 1")
    cx, cy = int(math.floor(x)), int(math.floor(y))
    distances = []
    for dy in (-1, 0, 1):
        for dx in (-1, 0, 1):
            gx, gy = cx + dx, cy + dy
            if wrap:
                key = (gx % width, gy % height)
            else:
                if not (0 <= gx < width and 0 <= gy < height):
                    continue
                key = (gx, gy)
            px, py = points[key]
            if wrap:
                px += (gx - key[0])
                py += (gy - key[1])
            ax, ay = abs(px - x), abs(py - y)
            if metric == "euclidean":
                distances.append(math.hypot(ax, ay))
            elif metric == "manhattan":
                distances.append(ax + ay)
            else:
                distances.append(max(ax, ay))
    if len(distances) < 2:
        raise ValueError("fewer than two feature points are in range")
    distances.sort()
    return {"f1": distances[0], "f2": distances[1],
            "edge": distances[1] - distances[0]}
